#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"

// Destination-passing-style entry. Per definition.json:
//   final_hidden_states: [batch_seq_len, 3072] bf16
//   expert_outputs:      [num_selected_tokens, 3072] bf16
//   token_indices:       [num_selected_tokens] int64
//   output (DPS):        [batch_seq_len, 3072] bf16
// hidden_size is pinned at 3072.

void run(
    torch::Tensor final_hidden_states,
    torch::Tensor expert_outputs,
    torch::Tensor token_indices,
    torch::Tensor output) {

    TORCH_CHECK(final_hidden_states.is_cuda(),
                "final_hidden_states must be CUDA");
    TORCH_CHECK(expert_outputs.is_cuda(),
                "expert_outputs must be CUDA");
    TORCH_CHECK(token_indices.is_cuda(),
                "token_indices must be CUDA");
    TORCH_CHECK(output.is_cuda(), "output must be CUDA");

    TORCH_CHECK(
        final_hidden_states.dtype() == torch::kBFloat16,
        "final_hidden_states must be bfloat16");
    TORCH_CHECK(
        expert_outputs.dtype() == torch::kBFloat16,
        "expert_outputs must be bfloat16");
    TORCH_CHECK(
        token_indices.dtype() == torch::kInt64,
        "token_indices must be int64");
    TORCH_CHECK(
        output.dtype() == torch::kBFloat16,
        "output must be bfloat16");

    TORCH_CHECK(final_hidden_states.is_contiguous() &&
                expert_outputs.is_contiguous() &&
                token_indices.is_contiguous() &&
                output.is_contiguous(),
                "all tensors must be contiguous");

    TORCH_CHECK(final_hidden_states.dim() == 2,
                "final_hidden_states must be 2D");
    TORCH_CHECK(expert_outputs.dim() == 2,
                "expert_outputs must be 2D");
    TORCH_CHECK(output.dim() == 2, "output must be 2D");
    TORCH_CHECK(
        final_hidden_states.size(1) == 3072,
        "hidden_size must be 3072");
    TORCH_CHECK(
        expert_outputs.size(1) == 3072,
        "expert_outputs last dim must be 3072");
    TORCH_CHECK(
        token_indices.size(0) == expert_outputs.size(0),
        "token_indices length must equal num_selected_tokens");
    TORCH_CHECK(
        output.size(0) == final_hidden_states.size(0) &&
        output.size(1) == final_hidden_states.size(1),
        "output must match final_hidden_states shape");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_008_expert_output_weighted_index_add_accumulation_launcher(
        final_hidden_states,
        expert_outputs,
        token_indices,
        output,
        stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "MoE expert-output atomic scatter-add accumulation. Phase 1 "
        "memcpy final_hidden_states → output, Phase 2 atomic bf16 "
        "scatter-add over (num_selected_tokens, hidden_size). "
        "Destination-passing style.");
}

#include "kernel.h"
#include <cuda_bf16.h>
#include <cuda_runtime.h>

// Two-phase MoE accumulation:
//   Phase 1: copy final_hidden_states → output (cudaMemcpyAsync on the
//            current stream).
//   Phase 2: for each (selected_token_idx i, hidden lane h):
//              atomicAdd(&output[token_indices[i] * H + h],
//                        expert_outputs[i * H + h])
//
// hidden_size=3072 is pinned by the problem definition. We tile the
// hidden axis across blockDim.x and use a 2D grid (selected_tokens,
// H_tiles). atomicAdd on `__nv_bfloat16` is available on compute
// capability >= 8.0 (sm_80+), which covers both the local 3090 Ti
// (sm_86) and the Phase-2 B200 (sm_100a) target.

namespace {

constexpr int HIDDEN_SIZE = 3072;
constexpr int BLOCK_THREADS = 256;

__global__ void __launch_bounds__(BLOCK_THREADS, 8)
index_add_kernel(
    const __nv_bfloat16* __restrict__ expert_outputs,
    const long* __restrict__ token_indices,
    __nv_bfloat16* __restrict__ output,
    int num_selected) {

    const int sel = blockIdx.x;
    if (sel >= num_selected) return;

    const int h_base = blockIdx.y * BLOCK_THREADS + threadIdx.x;
    if (h_base >= HIDDEN_SIZE) return;

    const long tok = token_indices[sel];
    const long src_off = static_cast<long>(sel) * HIDDEN_SIZE + h_base;
    const long dst_off = tok * HIDDEN_SIZE + h_base;

    const __nv_bfloat16 v = expert_outputs[src_off];
    atomicAdd(output + dst_off, v);
}

}  // namespace

void problem_008_expert_output_weighted_index_add_accumulation_launcher(
    const torch::Tensor& final_hidden_states,
    const torch::Tensor& expert_outputs,
    const torch::Tensor& token_indices,
    torch::Tensor& output,
    cudaStream_t stream) {

    const int batch_seq_len = static_cast<int>(final_hidden_states.size(0));
    const int H = static_cast<int>(final_hidden_states.size(1));
    const int num_selected = static_cast<int>(expert_outputs.size(0));
    (void)H;  // pinned at HIDDEN_SIZE; checked in main.cpp

    // Phase 1: byte-exact copy of the accumulation buffer into output.
    cudaMemcpyAsync(
        output.data_ptr<at::BFloat16>(),
        final_hidden_states.data_ptr<at::BFloat16>(),
        static_cast<size_t>(batch_seq_len) * HIDDEN_SIZE * sizeof(at::BFloat16),
        cudaMemcpyDeviceToDevice,
        stream);

    // Phase 2: atomic scatter-add expert_outputs into output rows
    // indexed by token_indices.
    const int h_tiles = (HIDDEN_SIZE + BLOCK_THREADS - 1) / BLOCK_THREADS;
    dim3 grid(num_selected, h_tiles);
    dim3 block(BLOCK_THREADS);
    index_add_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __nv_bfloat16*>(
            expert_outputs.data_ptr<at::BFloat16>()),
        token_indices.data_ptr<long>(),
        reinterpret_cast<__nv_bfloat16*>(
            output.data_ptr<at::BFloat16>()),
        num_selected);
}

#pragma once

#include <torch/extension.h>
#include <cuda_runtime.h>

// Host launcher for the MoE atomic-accumulation kernel.
// final_hidden_states: [batch_seq_len, hidden_size] bf16 — copied to output.
// expert_outputs:      [num_selected_tokens, hidden_size] bf16 — atomically
//                      added back into output[token_indices[i]] per row.
// token_indices:       [num_selected_tokens] int64.
// output:              [batch_seq_len, hidden_size] bf16 (DPS, pre-allocated).
// hidden_size is pinned at 3072 by the problem definition.
void problem_008_expert_output_weighted_index_add_accumulation_launcher(
    const torch::Tensor& final_hidden_states,
    const torch::Tensor& expert_outputs,
    const torch::Tensor& token_indices,
    torch::Tensor& output,
    cudaStream_t stream);
